<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { BedDouble, Users, CalendarCheck, ShieldCheck } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import { useWorkspace } from '../stores/workspace'
import { api, addDays, shiftName, downloadCSV } from '../services/api'
import ScheduleMatrix from '../components/ScheduleMatrix.vue'
import OverviewChart from '../components/OverviewChart.vue'
import ScheduleCancellation from '../components/ScheduleCancellation.vue'
const s=useWorkspace(), route=useRoute(), router=useRouter(), history=ref(false),cancellationOpen=ref(false)
const pub=computed(()=>s.data.publications.find(p=>String(p.id)===route.params.id))
const pubNurses=computed(()=>pub.value?Array.from(new Map(pub.value.entries.map(e=>[e.nurse,{...e,id:e.nurse}])).values()):[])
const overview=ref(null),overviewError=ref(''),overviewLoading=ref(false);let overviewVersion=0
const viewedPublicationState=computed(()=>{
  if(!pub.value)return ''
  const latest=s.data.publications.find(p=>p.start_date===pub.value.start_date)
  if(latest&&latest.id!==pub.value.id)return 'replaced'
  return overview.value?.publication?.id===pub.value.id?overview.value.publication.status:''
})
async function loadOverview(){const version=++overviewVersion,group=String(s.group);if(!group)return;overviewLoading.value=true
  try{const result=await api('overview/?'+new URLSearchParams({group}));if(version===overviewVersion&&group===String(s.group)){overview.value=result;overviewError.value=''}}
  catch(e){if(version===overviewVersion&&group===String(s.group))overviewError.value=e.message}
  finally{if(version===overviewVersion)overviewLoading.value=false}}
async function cancellationChanged(){await s.load(true);await loadOverview()}
watch(()=>s.group,(group,old)=>{if(String(group)!==String(old)){overview.value=null;overviewError.value=''}loadOverview()},{immediate:true})
watch(()=>s.data?.server_time,loadOverview)
watch(()=>route.params.id,(id,old)=>{if(!id&&old)loadOverview()})
const staffing=computed(()=>({meets:'配置满足',insufficient:'人员不足',unconfigured:'暂无法完成整体评价',no_schedule:'正式排班缺失',needs_review:'尚需核查',unavailable:'排班数据暂不可用'})[overview.value?.staffing?.status]||'暂无法获取')
const shiftStatus=item=>({meets:'配置满足',insufficient:'人员不足',unconfigured:'最低需求未配置',no_schedule:'正式排班缺失',disabled:'班次未启用',rest:'休息班次',unavailable:'排班数据暂不可用'})[item.status]||'暂无法获取'
const validationText=report=>!report?'尚未执行校验':report.status==='blocking'?`阻断 ${report.blocking} 项 · 提示 ${report.warnings} 项`:report.status==='warnings'?`无阻断 · 提示 ${report.warnings} 项`:report.status==='passed'?'已校验无阻断':report.status==='no_effective_schedule'?'暂无有效正式排班':'校验暂不可用'
async function goAlert(item){if(item.route==='/beds'&&item.date&&item.shift){s.date=item.date;s.shift=item.shift;try{await s.load(true)}catch(e){ElMessage.error('切换分床日期失败：'+e.message);return}}router.push(item.route)}
function exportSchedule(){downloadCSV('已发布排班-'+pub.value.id+'.csv',[['护士','日期','班次','工时'],...pub.value.entries.map(e=>[e.name,e.date,shiftName(e.shift),e.hours])])}
function printPage(){window.print()}
</script>
<template>
  <template v-if="route.params.id"><div class="page-heading"><div><el-button link type="primary" @click="router.push('/overview')">‹ 返回总览</el-button><h1>已发布排班 <el-tag type="success">只读正式版本 #{{pub?.id}}</el-tag></h1></div><div class="export-actions"><el-button :disabled="!pub" @click="exportSchedule">导出排班表</el-button><el-button @click="printPage">打印排班表</el-button><el-button @click="history=true">查看历史版本</el-button></div></div><el-alert v-if="viewedPublicationState==='partially_cancelled'" title="本页展示原始发布快照；该版本部分班次已撤销，当前有效班次请查看总览或排班管理。" type="warning" :closable="false"/><el-alert v-else-if="viewedPublicationState==='cancelled'" title="本页展示已撤销版本的原始快照，不代表当前有效排班。" type="warning" :closable="false"/><el-alert v-else-if="viewedPublicationState==='replaced'" title="本页展示历史发布快照，该周期已有更新的正式版本。" type="info" :closable="false"/><div v-if="pub" class="card"><h3>{{s.data.group.name}} · {{pub.start_date}} 至 {{pub.end_date}}</h3><p class="muted small">发布人：{{pub.published_by}} · 发布时间：{{new Date(pub.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</p><ScheduleMatrix :entries="pub.entries" :nurses="pubNurses" :start="pub.start_date" :duration="pub.duration_days"/></div><el-empty v-else description="此版本不存在或超出当前可见范围"/></template>
  <template v-else><div class="page-heading"><div><h1>总览</h1><p>实时掌握病区运行情况与正式排班信息</p></div><el-tag effect="plain">{{overview?.group.name||s.data.group.name}} · {{overview?.date||s.data.today}}</el-tag></div>
  <el-alert v-if="overviewError" :title="'总览数据读取失败：'+overviewError+(overview?'；以下为上次获取的数据，可能已过期。':'')" type="error" :closable="false"/>
  <p v-if="overviewLoading&&!overview" class="muted">正在加载总览数据…</p>
  <template v-if="overview"><div class="overview-grid">
    <section class="card"><div class="card-title"><h2><BedDouble :size="20"/> 病区概况（今日）</h2><small class="muted">更新：{{new Date(overview.updated_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</small></div>
      <div class="overview-metrics"><div v-for="[label,value,unit] in [['开放床位',overview.beds,'床'],['在床患者',overview.patients,'人'],['今日新入科',overview.admissions,'人'],['今日转出／出院',overview.discharges,'人']]" :key="label" class="overview-metric"><strong>{{value===null?'—':value}} <small v-if="value!==null">{{unit}}</small></strong><span>{{label}}</span><small v-if="value===null" class="muted">暂无可靠数据来源</small><small v-else-if="label==='在床患者'" class="muted">合成 {{overview.synthetic_patients}} · 非合成 {{overview.non_synthetic_patients}}</small></div></div>
    </section>
    <section class="card"><div class="card-title"><h2><CalendarCheck :size="20"/> 本周排班 <el-tag v-if="overview.publication" :type="overview.publication.status==='published'?'success':overview.publication.status==='cancelled'?'info':'warning'">{{({published:'已发布',partially_cancelled:'部分撤销',cancelled:'已撤销',replaced:'已被替代'})[overview.publication.status]}}</el-tag></h2><div class="actions"><el-button v-if="s.canEdit" type="danger" plain :disabled="!overview.publication?.effective_records||overview.publication?.multiple_versions||overview.group.id!==s.data.group.id" @click="cancellationOpen=true">撤销正式排班</el-button><el-button v-if="overview.publication" type="primary" plain @click="router.push('/overview/published/'+overview.publication.id)">查看完整排班 →</el-button></div></div>
      <el-alert v-if="overview.publication?.status==='cancelled'" title="当前周期暂无有效正式排班；历史版本及撤销记录保留。" type="warning" :closable="false"/><el-alert v-else-if="overview.publication?.status==='partially_cancelled'" title="正式排班部分撤销，待重新校验。" type="warning" :closable="false"/><p v-if="overview.has_pending_draft" class="small muted">存在待审核排班草稿，尚未成为正式排班。</p>
      <p v-if="overview.publication?.uncovered_dates?.length&&overview.publication.effective_records" class="small muted">未见有效正式班次的日期：{{overview.publication.uncovered_dates.join('、')}}</p>
      <p v-if="overview.publication?.last_cancellation" class="small muted">最近撤销 #{{overview.publication.last_cancellation.id}} · {{new Date(overview.publication.last_cancellation.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} · {{overview.publication.last_cancellation.actor}} · {{overview.publication.last_cancellation.reason}}</p>
      <template v-if="overview.publication"><h3>{{overview.group.name}} · {{overview.week_start}} 至 {{addDays(overview.week_start,6)}}</h3><p class="muted small">正式版本 #{{overview.publication.id}} · {{overview.publication.published_by}} · {{new Date(overview.publication.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</p><el-alert v-if="overview.publication.multiple_versions" type="warning" :closable="false" :title="'本周不同日期涉及多个正式版本：'+overview.publication.version_ids.map(id=>'#'+id).join('、')+'；请至排班管理按版本核对。'"/><div class="overview-metrics compact"><div v-for="([label,value,unit],index) in [['参与排班护士',overview.publication.nurse_count,'人'],['轮转小组',overview.publication.subgroups,'个'],['排班周期',overview.publication.days,'天'],['待处理排班异常',overview.publication.anomalies,'项']]" :key="label" :class="['overview-metric',{'metric-danger':index===3&&overview.validation.status==='blocking'}]"><strong>{{value===null?'—':value}} <small v-if="value!==null">{{unit}}</small></strong><span>{{label}}</span><small v-if="index===3" class="muted">{{validationText(overview.validation)}}</small></div></div></template><el-empty v-else :description="overview.data_quality.schedule==='unavailable'?'正式排班数据暂无法读取':'本周暂无已发布排班'" :image-size="60"/>
    </section>
    <section class="card"><div class="card-title"><h2>班次人力配置（今日）</h2><el-tag size="small" effect="plain">正式排班来源</el-tag></div><div class="shift-cards"><div v-for="item in overview.shifts" :key="item.code" :class="['shift-card',item.status]"><b>{{item.name}}</b><small>{{item.start?item.start+'–'+(item.next_day?'次日':'')+item.end:'夜班后休息'}}</small><p>有效排班 <strong>{{item.count===null?'—':item.count}}</strong> 人</p><p>{{item.code==='POST'?'最低需求不适用':item.need===null?'最低需求未配置':'最低需求 '+item.need+' 人'}}</p><div class="shift-ring" :style="{'--portion':Math.min(item.coverage??0,100)+'%'}"><b>{{item.coverage===null?'—':item.coverage+'%'}}</b></div><small>{{item.coverage===null?shiftStatus(item):'排班覆盖率'}}</small></div></div><p class="muted small section-gap">正式排班不代表实际到岗；N班按开始日期统计。<span v-if="!overview.requirements_confirmed">当前人数规则尚未由科室确认。</span></p></section>
    <section class="card"><div class="card-title"><h2><ShieldCheck :size="20"/> 人力充足性评估</h2><small class="muted">依据当前配置人数</small></div><div class="staffing-summary"><div :class="['staffing-indicator',overview.staffing.status]">{{staffing}}</div><div><p v-for="item in overview.shifts.filter(x=>x.code!=='POST')" :key="item.code"><b>{{item.name}}</b>：<span :class="['staffing-status',item.status]">{{shiftStatus(item)}}</span> <span class="muted small">（排班 {{item.count??'—'}} / 最低 {{item.need??'—'}}）</span></p></div></div><p v-if="overview.staffing.missing_requirements.length" class="small muted">最低需求未配置：{{overview.staffing.missing_requirements.join('、')}}</p><p v-if="!overview.requirements_confirmed" class="small rule-warning">当前人数规则尚未由科室确认，计算仅供核对配置。</p><p class="muted small">{{overview.staffing.note}}</p></section>
    <section class="card"><h2>护士能力结构（未离职档案 {{overview.nurses_total}} 人）</h2><div class="ability-charts"><div><h3>护理层级结构</h3><OverviewChart kind="levels" :data="overview.levels"/></div><div><h3>专科技能及有效独立资格</h3><OverviewChart kind="skills" :data="overview.skills"/><small class="muted">按启用技能及有效资格分别统计。</small></div></div></section>
    <section class="card"><div class="card-title"><h2>重点提示</h2><el-button link type="primary" @click="history=true">排班历史</el-button></div><div v-if="overview.alerts.length"><div v-for="(item,index) in overview.alerts" :key="index" :class="['issue',item.level]"><b>{{index+1}}. {{item.title}}</b><p>{{item.detail}}</p><el-button link type="primary" @click="goAlert(item)">前往处理 →</el-button></div></div><el-empty v-else :description="overview.data_quality.admission_events==='unavailable'||overview.data_quality.discharge_events==='unavailable'?'入出科事件数据尚未接入，无法完成全部状态检查':'当前暂无待处理的重要业务事项'" :image-size="60"/></section>
  </div></template></template>
  <el-drawer v-model="history" title="排班发布历史" size="490px"><div v-for="p in s.data.publications" :key="p.id" class="notice"><b>{{p.start_date}} · 版本 #{{p.id}}</b><p class="muted small">{{new Date(p.created_at).toLocaleString('zh-CN')}} / {{p.published_by}}</p><el-button @click="history=false;router.push('/overview/published/'+p.id)">查看只读版本</el-button></div></el-drawer>
  <ScheduleCancellation v-if="overview?.publication" v-model="cancellationOpen" :formal-publication="overview.publication" :group="s.group" :week="overview.publication.start_date" :nurses="s.data.nurses" :shifts="s.data.shifts" :phases="s.data.group.rules.phases" @changed="cancellationChanged"/>
</template>

<style scoped>
.overview-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:12px}.overview-grid>.card+.card{margin-top:0}.overview-grid h2{display:flex;align-items:center;gap:7px}.overview-grid h3{font-size:14px}.overview-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.overview-metric{background:#f1f7ff;border-radius:7px;padding:12px;display:flex;flex-direction:column;gap:5px;min-width:0}.overview-metric:nth-child(2){background:#eefaf6}.overview-metric:nth-child(3){background:#fff8ef}.overview-metric:nth-child(4){background:#f7f3ff}.overview-metric strong{font-size:23px;color:#1269dc}.overview-metric strong small{font-size:12px}.overview-metric span{font-size:12px}.overview-metrics.compact .overview-metric{padding:9px}.shift-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.shift-card{background:#f5f9ff;border-radius:7px;padding:10px;text-align:center;display:flex;flex-direction:column;gap:5px}.shift-card p{margin:2px 0;font-size:12px}.shift-card small{font-size:11px;color:#6c8098}.shift-ring{height:62px;width:62px;border-radius:50%;margin:3px auto;display:grid;place-items:center;background:conic-gradient(#3188fa var(--portion),#e1eaf5 0);position:relative}.shift-ring:before{content:'';position:absolute;inset:6px;background:#fff;border-radius:50%}.shift-ring b{z-index:1;font-size:13px}.staffing-summary{display:flex;align-items:center;gap:24px}.staffing-indicator{flex:none;width:145px;height:145px;border:12px solid #dce9f8;border-radius:50%;display:grid;place-items:center;text-align:center;color:#41698c;font-weight:bold}.staffing-summary p{margin:12px 0}.ability-charts{display:grid;grid-template-columns:1fr 1fr;gap:12px}.issue{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:2px 8px}.issue b,.issue p{grid-column:1}.issue p{margin:4px 0;font-size:12px;overflow-wrap:anywhere}.issue .el-button{grid-column:2;grid-row:1 / 3;align-self:center}.issue.danger{background:#fff1f1;color:#c64848}@media(max-width:1050px){.overview-grid{grid-template-columns:1fr}}@media(max-width:650px){.overview-metrics,.shift-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.ability-charts{grid-template-columns:1fr}.staffing-summary{flex-wrap:wrap}}
.overview-metric:nth-child(2) strong{color:#168f78}.overview-metric:nth-child(3) strong{color:#c77c22}.overview-metric:nth-child(4) strong{color:#7851b8}.overview-metric.metric-danger{background:#fff0f0}.overview-metric.metric-danger strong{color:#c64c4c}.shift-card:nth-child(2){background:#eefaf6}.shift-card:nth-child(3){background:#f7f3ff}.shift-card:nth-child(4){background:#f6f8fb}.shift-card.meets{--ring-color:#28b694}.shift-card.insufficient{--ring-color:#e7a13e}.shift-card.unconfigured,.shift-card.no_schedule,.shift-card.disabled,.shift-card.rest{--ring-color:#b7c9db}.shift-ring{background:conic-gradient(var(--ring-color,#b7c9db) var(--portion),#e1eaf5 0)}.staffing-indicator.meets{border-color:#6bcfb4;color:#198d75}.staffing-indicator.insufficient{border-color:#edbb74;color:#b9711e}.staffing-indicator.unconfigured,.staffing-indicator.no_schedule,.staffing-indicator.needs_review{font-size:13px;line-height:1.5;padding:12px}.staffing-status.meets{color:#168f78}.staffing-status.insufficient,.rule-warning{color:#b8751f}.issue.warning{background:#fff8ed;color:#9c681d}.issue.info{background:#eef6ff;color:#436a94}.issue{border-radius:7px;padding:10px;margin:7px 0}
.ability-charts{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.ability-charts>div{min-width:0}@media(max-width:650px){.ability-charts{grid-template-columns:1fr}}
</style>
